const { withXcodeProject, IOSConfig } = require("@expo/config-plugins");
const fs = require("fs");
const path = require("path");

/**
 * Puts plugins/ios/BudgetAppIntents.swift into the Xcode project.
 *
 * ios/ is gitignored and regenerated by `expo prebuild`, so a Swift file
 * dropped in there by hand disappears the next time anyone prebuilds. This
 * plugin copies it in and adds it to the app target's Sources phase on every
 * prebuild, which is what makes the Siri shortcuts survive a clean checkout.
 *
 * No entitlement and no extension target: the intents are declared in the main
 * app target, so iOS 16+ discovers them from the app binary's generated
 * Metadata.appintents bundle. The reasoning is in the Swift file's header.
 *
 * There is no Expo module for App Intents — this is the supported way to add
 * native code to a managed project, not a workaround for a missing one.
 */
const SOURCE = path.join("plugins", "ios", "BudgetAppIntents.swift");
const FILENAME = "BudgetAppIntents.swift";

module.exports = function withAppIntents(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const projectRoot = cfg.modRequest.projectRoot;
    const platformRoot = cfg.modRequest.platformProjectRoot;
    // The group name is the Xcode project's own name — for this app, "Budget".
    const groupName = IOSConfig.XcodeUtils.getProjectName(projectRoot);

    const from = path.join(projectRoot, SOURCE);
    if (!fs.existsSync(from)) {
      throw new Error(`[withAppIntents] missing ${SOURCE} — the Siri intents cannot be built.`);
    }

    const to = path.join(platformRoot, groupName, FILENAME);
    fs.mkdirSync(path.dirname(to), { recursive: true });
    fs.copyFileSync(from, to);

    // Prebuild can run against an ios/ that already has the reference. Adding
    // it twice gives Xcode duplicate symbols, so ask before adding.
    const alreadyLinked = Object.values(project.pbxBuildFileSection() || {}).some(
      (entry) => typeof entry === "object" && entry?.fileRef_comment === FILENAME,
    );
    if (!alreadyLinked) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({
        filepath: `${groupName}/${FILENAME}`,
        groupName,
        project,
      });
    }

    return cfg;
  });
};
